const CMS_BASE=document.documentElement.dataset.base||'';
/* 1DED Free CMS — framework-free admin, no external scripts or tracking. */
const $=s=>document.querySelector(s), app=$('#app');
const E=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',page:'<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><path d="M14 2v6h6M8 13h8M8 17h6"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',image:'<rect x="3" y="3" width="18" height="18" rx="2"/><circle cx="8" cy="8" r="1.5"/><path d="m21 15-5-5L5 21"/>',palette:'<path d="M12 3a9 9 0 1 0 0 18h1a2 2 0 0 0 1-3.5c-1-.8-.4-2.5 1-2.5h2a4 4 0 0 0 4-4c0-5-4-8-9-8Z"/><circle cx="7.5" cy="10" r=".6"/><circle cx="10" cy="6.5" r=".6"/><circle cx="15" cy="7" r=".6"/>',mail:'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 6 9 7 9-7"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 5 5"/>',settings:'<path d="m9 3-1 3-3 1-2 3 2 3 1 3 3 1 2 4 3-2 3-1 1-3 3-2-2-3-1-3-3-1-3-2z"/><circle cx="12" cy="12" r="3"/>',globe:'<circle cx="12" cy="12" r="9"/><ellipse cx="12" cy="12" rx="4" ry="9"/><path d="M3 12h18"/>',arrow:'<path d="M7 17 17 7M7 7h10v10"/>',plus:'<path d="M12 5v14M5 12h14"/>',publish:'<path d="M12 16V3m-5 5 5-5 5 5M4 15v5h16v-5"/>',shield:'<path d="m12 3 8 4v6c0 5-8 8-8 8s-8-3-8-8V7z"/><path d="m8 12 3 3 5-6"/>',logout:'<path d="M9 4H4v16h5m5-4 4-4-4-4m-6 4h10"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',check:'<path d="m5 12 4 4L19 6"/>',trash:'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7"/>',copy:'<rect x="8" y="8" width="13" height="13" rx="2"/><path d="M16 8V3H3v13h5"/>',code:'<path d="m8 5-6 7 6 7m8-14 6 7-6 7m-3-17-2 20"/>'};
const I=name=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.page}</svg>`;
const uid=()=>crypto.randomUUID();
let autosaveTimer,saveInFlight=null,editGeneration=0,autosavePaused=false;
let availableStarters=[];
let state, view='dashboard', page=null, sectionIndex=0, editTab='content', dirty=false, busy=false, authMode='login';
const date=value=>value?new Date(value).toLocaleString(undefined,{dateStyle:'medium',timeStyle:'short'}):'Not published yet';
function toast(text,error=false){const el=$('#toast');el.textContent=text;el.className=error?'error':'';el.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.style.display='none',5000);}
function confirmAction(title,text){return new Promise(resolve=>{const d=$('#confirm');$('#confirm-title').textContent=title;$('#confirm-text').textContent=text;d.showModal();$('#confirm-yes').onclick=()=>{d.close();resolve(true);};$('#confirm-no').onclick=()=>{d.close();resolve(false);};d.oncancel=()=>resolve(false);});}
async function api(path,method='GET',data){const res=await fetch(CMS_BASE+'/api'+path,{method,headers:{...(data instanceof Blob?{'Content-Type':data.type}:{'Content-Type':'application/json'}),...(state?.csrf?{'X-CSRF-Token':state.csrf}:{})},body:data===undefined?undefined:data instanceof Blob?data:JSON.stringify(data)});const json=await res.json();if(!res.ok){if(res.status===401&&state){state=null;authView();}throw new Error(json.error||'Request failed.');}return json;}
function markDirty(){dirty=true;editGeneration++;queueAutosave();const el=$('#save-status');if(el){el.textContent='Unsaved changes';el.className='dirty';}}
async function refresh(){state=await api('/state');}
async function navigate(next){clearTimeout(autosaveTimer);if(saveInFlight)await saveInFlight;if(dirty&&!await confirmAction('Leave without saving?','Your unsaved edits will be discarded.'))return;dirty=false;view=next;page=null;await refresh();render();window.scrollTo(0,0);}
function btn(label,action,icon='',cls='',extra=''){return `<button type="button" class="btn ${cls}" data-action="${action}" ${extra}>${icon?I(icon):''}${label}</button>`;}
function field(label,name,value='',type='text',help=''){return `<label>${E(label)}${type==='textarea'?`<textarea name="${E(name)}" rows="4">${E(value)}</textarea>`:`<input type="${type}" name="${E(name)}" value="${E(value)}" ${type==='password'?'minlength="12" maxlength="256" autocomplete="new-password"':''}>`}${help?`<small>${E(help)}</small>`:''}</label>`;}
function select(label,name,value,options){return `<label>${E(label)}<select name="${E(name)}">${options.map(o=>{const [v,l]=Array.isArray(o)?o:[o,o];return `<option value="${E(v)}" ${value===v?'selected':''}>${E(l)}</option>`;}).join('')}</select></label>`;}
const logo=()=>'<div class="logo"><span class="logo-mark">1</span><div><strong>1DED</strong><small>FREE CMS</small></div></div>';
function authView(error=''){const setup=authMode==='setup';if(setup){location.href=CMS_BASE+'/install/';return;}app.innerHTML=`<div class="auth-shell"><section class="auth-story">${logo()}<div><h1>Your ideas.<br>Your website.<br>Your own space.</h1><p>A thoughtful little CMS for making something that’s entirely yours.</p></div><footer>OPEN SOURCE. SELF HOSTED. ALWAYS YOURS.</footer></section><main class="auth-main"><form class="auth-form" id="auth-form"><h2>${setup?'Make yourself at home.':'Welcome back.'}</h2><p>${setup?'A few details, and your new website is ready to begin.':'Sign in to your studio. Let’s make something good.'}</p>${error?`<div class="error" role="alert">${E(error)}</div>`:''}${setup?field('Installation token','token','','password','Find your private token in the server terminal.')+field('Website name','name','My Website')+field('Website URL','url',location.origin+CMS_BASE,'url')+select('Website starter','preset','company',availableStarters.length?availableStarters.map(p=>[p.id,p.name]):[['business','Company / business'],['personal','Personal / biography'],['portfolio','Portfolio']]):''}${field('Email address','email','','email')}<label>Password<input type="password" name="password" required minlength="12" maxlength="256" autocomplete="${setup?'new-password':'current-password'}"></label>${setup?'<p class="footnote">Use at least 12 characters. A passphrase works well.</p>':''}<button class="btn primary" type="submit">${setup?'Create my website':'Sign in to your studio'} ${I('arrow')}</button><p class="footnote">${setup?'No subscriptions. No cloud account. Your content belongs to you.':'Forgot your password? Use the recovery code saved during installation at '+location.origin+CMS_BASE+'/recover/.'}</p></form></main></div>`;}
function navButton(name,label,icon,badge=''){return `<button class="nav-button ${view===name?'active':''}" data-nav="${name}">${I(icon)}${label}${badge?`<span class="count">${badge}</span>`:''}</button>`;}
function render(){if(!state)return;const owner=state.user.role==='owner',unread=state.messages.filter(m=>m.status==='new').length;app.innerHTML=`<aside class="sidebar">${logo()}<div class="site-switch"><span class="site-avatar">${E(state.site.name[0])}</span><div><strong>${E(state.site.name)}</strong><small>Your workspace · ${owner?'Owner':'Editor'}</small></div></div><div class="nav-label">WORKSPACE</div>${navButton('dashboard','Overview','grid')}${navButton('pages','Pages','page',state.pages.length)}${owner?navButton('navigation','Navigation','menu'):''}${navButton('categories','Categories','grid')}${navButton('links','Saved links','arrow')}${navButton('media','Media library','image')}${navButton('trash','Trash','trash',state.trash?.length||'')}${owner?navButton('appearance','Templates & design','palette'):''}${navButton('inbox','Form inbox','mail',unread||'')}<div class="nav-label">MANAGE</div>${owner?navButton('seo','SEO & discovery','search')+navButton('publishing','Publishing','publish')+navButton('settings','Site settings','settings'):''}${owner?navButton('maintenance','Updates & backups','shield'):''}${navButton('account','Account & security','shield')}<div class="sidebar-bottom"><a class="nav-button" href="/" target="_blank" rel="noopener">${I('globe')}View website ${I('arrow')}</a><button class="nav-button" data-action="logout">${I('logout')}Sign out</button><div class="sidebar-foot"><div class="user-avatar">${E(state.user.email[0].toUpperCase())}</div><div><div class="user-email">${E(state.user.email)}</div><small style="font-size:9px">${owner?'Website owner':'Content editor'}</small></div></div></div></aside><main class="main"><header class="topbar"><div class="breadcrumb"><button class="mobile-menu" data-action="mobile" aria-label="Open navigation">${I('menu')}</button><span>Workspace</span><span>/</span><strong>${E(({dashboard:'Overview',pages:'Pages',navigation:'Navigation',media:'Media library',appearance:'Templates & design',inbox:'Form inbox',seo:'SEO & discovery',publishing:'Publishing',settings:'Site settings',account:'Account & security',editor:'Page editor',categories:'Categories',links:'Saved links',trash:'Trash',maintenance:'Updates & backups',starters:'Templates & design'})[view]||view)}</strong></div><div class="topbar-right"><span class="live-indicator">${state.current?'Website is live':'Ready when you are'}</span><a class="btn" href="/" target="_blank" rel="noopener">View website ${I('arrow')}</a>${owner?btn('Publish website','publish','publish','primary'):''}</div></header><div class="content" id="content"></div></main>`;const screens={dashboard,pages,navigation,media,appearance,inbox,seo,publishing,settings,account,editor,categories:categoryScreen,links:linkScreen,trash:trashScreen,maintenance:maintenanceScreen,starters:starterScreen};$('#content').innerHTML=(screens[view]||dashboard)();if(view==='maintenance')loadHostingHealth();if(view==='account')loadUsers();if(view==='links')loadLinkCheck();if(view==='editor'&&editTab==='history')loadHistory();}
const heading=(title,desc,actions='')=>`<div class="page-head"><div><h1>${title}</h1><p>${desc}</p></div><div class="actions">${actions}</div></div>`;
function pageRows(list=state.pages){return list.map(p=>`<tr><td><div class="cell-title"><span class="file-icon">${I('page')}</span><div><strong>${E(p.title)}</strong><small>/${E(p.slug)}${p.slug?'/':''} · ${E(p.kind||'page')}</small><small>${(p.categories||[]).map(id=>E(state.categories.find(c=>c.id===id)?.name||'')).filter(Boolean).join(' · ')}</small></div></div></td><td><span class="tag ${p.status==='draft'?'draft':''}">${p.status==='draft'?'Draft':'Included in next publish'}</span></td><td><small>${p.sections.length} sections</small></td><td><div class="actions">${btn('Edit','edit','', '',`data-id="${E(p.id)}"`)}<a class="btn icon-only" aria-label="Preview ${E(p.title)}" href="/preview/${E(p.id)}" target="_blank" rel="noopener">${I('arrow')}</a></div></td></tr>`).join('');}
function dashboard(){const published=state.pages.filter(p=>p.status==='published').length,unread=state.messages.filter(m=>m.status==='new').length,home=state.pages.find(p=>p.slug==='')||state.pages[0];return heading('A little space for big ideas.','Welcome to your studio. Here’s how your website is coming along.',btn('Add a page','new-page','plus'))+`<div class="stats">${[['Pages',state.pages.length,'Your story, one page at a time','page'],['Ready to publish',published,'Pages included in your next build','globe'],['New messages',unread,'Conversations waiting for you','mail'],['Theme',state.site.theme[0].toUpperCase()+state.site.theme.slice(1),'A style that feels like you','palette']].map(([label,value,note,icon])=>`<div class="stat"><div class="stat-label">${label}${I(icon)}</div><strong>${value}</strong><small>${note}</small></div>`).join('')}</div><div class="dashboard-grid"><div><section class="panel"><div class="panel-head"><h2>Your website, at a glance</h2><span class="tag neutral">Draft preview</span></div><div class="website-preview"><div class="browser-chrome"><i></i><i></i><i></i><span>${E(state.site.url)}</span></div><div class="mini-site">${home?`<iframe title="Homepage draft preview" src="/preview/${E(home.id)}" tabindex="-1"></iframe>`:''}</div></div><div class="preview-footer"><div><strong style="font-size:12px">${E(state.site.name)}</strong><p style="font-size:10px">${E(state.site.tagline)}</p></div>${btn('Customize','go-appearance','palette')}</div></section><section class="panel"><div class="panel-head"><h2>Your pages</h2><button class="btn subtle" data-nav="pages">Manage pages ${I('arrow')}</button></div><div class="table-wrap"><table><thead><tr><th>Page</th><th>Status</th><th>Content</th><th></th></tr></thead><tbody>${pageRows(state.pages.slice(0,4))}</tbody></table></div></section></div><div><section class="panel"><div class="panel-head"><h2>Make it yours</h2><small>A good place to start</small></div><div class="panel-body"><div class="checklist">${[[true,'Your studio is ready','A home for your next great idea.'],[state.site.url!=='https://example.com','Set your website details','Name, address, and a little personality.'],[state.pages.some(p=>p.updatedAt),'Tell your story','Make the sample pages your own.'],[!!state.current,'Share it with the world','Publish when everything feels right.']].map(([ok,title,note])=>`<div class="checklist-row"><span class="checkmark ${ok?'':'pending'}">${ok?'✓':'·'}</span><div><strong>${title}</strong><small>${note}</small></div></div>`).join('')}</div></div></section><section class="panel"><div class="panel-head"><h2>A few shortcuts</h2></div><div class="panel-body quick-grid">${[['new-page','page','New page','Room for another idea'],['go-media','image','Upload media','A picture says more'],['go-navigation','menu','Edit navigation','Help people find their way'],['go-seo','search','SEO check','Make yourself discoverable']].filter(x=>state.user.role==='owner'||!['go-navigation','go-seo'].includes(x[0])).map(([a,i,t,d])=>`<button class="quick" data-action="${a}">${I(i)}<span><strong>${t}</strong><small>${d}</small></span></button>`).join('')}</div></section><div class="banner"><div class="eyebrow">MADE FOR INDEPENDENCE</div><h3>Your website.<br>On your terms.</h3><p>Open source, portable, and free to make your own. That’s the 1DED way.</p></div></div></div><div class="footer-caption">1DED FREE CMS · SMALL BY DESIGN. YOURS BY DEFAULT.</div>`;}
function pages(){return heading('Your content, well organized.','Pages, articles, projects, services, and people.',btn('Add content','new-page','plus','primary'))+`<section class="panel"><div class="panel-head"><div class="actions"><h2>Content library</h2><select id="kind-filter" aria-label="Filter content type" style="width:150px;margin:0"><option value="">All content types</option>${[['page','Pages'],['post','Blog posts'],['project','Projects'],['service','Services'],['product','Products'],['member','Team members']].map(([v,l])=>`<option value="${v}">${l}</option>`).join('')}</select><select id="category-filter" aria-label="Filter category" style="width:150px;margin:0"><option value="">All categories</option>${state.categories.map(c=>`<option value="${E(c.id)}">${E(c.name)}</option>`).join('')}</select></div><label class="search" style="margin:0">${I('search')}<input id="page-search" aria-label="Search pages" placeholder="Find content…"></label></div><div class="table-wrap"><table><thead><tr><th>Content</th><th>Publication setting</th><th>Sections</th><th>Actions</th></tr></thead><tbody id="page-rows">${pageRows()}</tbody></table></div></section><p style="font-size:11px;margin-top:15px">Posts appear in /blog/. Categories generate their own public archives after publication. <a href="/search/" target="_blank" rel="noopener">Website search ↗</a></p>`;}
function editor(){if(!page)return '';return heading(E(page.title),'Build your page, section by section.',`<span id="save-status">${dirty?'Unsaved changes':'All changes saved'}</span>${btn('Back','back-pages')}${btn('Save page','save-page','check','primary')}`)+`<div class="tabs"><button data-tab="content" class="${editTab==='content'?'active':''}">Content</button><button data-tab="details" class="${editTab==='details'?'active':''}">Page & SEO</button><button data-tab="history" class="${editTab==='history'?'active':''}">Page history</button><button data-tab="preview" class="${editTab==='preview'?'active':''}">Preview saved draft ↗</button></div>${editTab==='content'?`<div class="editor"><aside class="panel editor-outline"><div class="panel-head"><h2>Sections</h2><small>${page.sections.length}</small></div><div class="panel-body" style="padding:10px">${page.sections.map((s,i)=>`<div class="section-row ${i===sectionIndex?'active':''}"><button class="section-name" data-action="section" data-index="${i}">${E(s.type)}${s.hidden?' · hidden':''}<br><small>${E(s.title?.slice(0,26)||'Untitled section')}</small></button><div class="section-actions"><button data-action="section-up" data-index="${i}" aria-label="Move section up">↑</button><button data-action="section-down" data-index="${i}" aria-label="Move section down">↓</button></div></div>`).join('')}<div style="padding:10px">${select('Add a section','new-section-type','text',['hero','text','features','image','gallery','timeline','testimonials','faq','cta','contact','links','collection','pricing'])}${btn('Add section','add-section','plus','','style="width:100%"')}</div></div></aside><section class="panel"><div class="panel-head"><h2>${E(page.sections[sectionIndex]?.type||'Page content')} section</h2><div class="actions">${page.sections.length?btn('Duplicate','duplicate-section','copy')+btn('Remove','remove-section','trash','danger'):''}</div></div><div class="panel-body">${sectionForm()}</div></section></div>`:editTab==='details'?pageDetails():editTab==='history'?'<section class="panel"><div class="panel-head"><h2>Earlier saved versions</h2></div><div id="history-list" class="panel-body">Loading history…</div></section>':`<div class="notice">This preview shows your last saved draft. Save first to include your latest edits. Internal links open published pages.</div><iframe title="Saved page preview" class="preview-frame" src="/preview/${E(page.id)}"></iframe>`}`;}
function imageInput(label,name,value){return `<label>${E(label)}<input name="${E(name)}" value="${E(value)}" list="media-urls" placeholder="Choose or paste a media path"><small>Upload your own image in the media library, or choose one of the bundled sample images.</small></label>`;}
function sectionForm(){const s=page.sections[sectionIndex];if(!s)return '<div class="empty"><h3>A blank canvas.</h3><p>Add your first section to get started.</p></div>';if(s.type==='pricing')return pricingForm(s);const itemTypes=['features','gallery','timeline','testimonials','faq'];return `<form id="section-form"><label class="check"><input type="checkbox" name="hidden" ${s.hidden?'checked':''}>Hide this section</label><div class="form-grid">${field('Eyebrow / small label','eyebrow',s.eyebrow)}${field('Heading','title',s.title,'textarea')}<div class="span-2">${richField('Body text','text',s.text)}</div>${['hero','cta'].includes(s.type)?field('Button label','button',s.button)+select('Link to a page','linkPage',s.linkPage||'',[['','Use a custom URL'],...state.pages.map(p=>[p.id,p.title])])+field('Custom button URL','link',s.link,'text','A selected page takes priority and follows URL changes.'):''}${['links','collection'].includes(s.type)?select('Link category','linkCategory',s.linkCategory||'',[['','All saved links'],...state.categories.map(c=>[c.id,c.name])]):''}${s.type==='collection'?select('Content type to display','collectionKind',s.collectionKind||'post',[['post','Blog posts'],['project','Projects'],['service','Services'],['member','Team members'],['page','Pages']])+field('Maximum items','itemLimit',s.itemLimit||6,'number'):''}${['hero','image'].includes(s.type)?imageInput('Image','image',s.image)+field('Image description (alt text)','alt',s.alt):''}</div>${itemTypes.includes(s.type)?`<h3 style="margin:10px 0 18px">${s.type==='faq'?'Questions & answers':'Items'}</h3>${(s.items||[]).map((item,i)=>`<div class="item-editor"><div class="item-head"><h4>Item ${i+1}</h4><div class="actions">${btn('↑','item-up','','',`data-index="${i}" aria-label="Move item up"`)}${btn('Remove','remove-item','trash','danger',`data-index="${i}"`)}</div></div><div class="form-grid">${field(s.type==='faq'?'Question':'Title',`item.${i}.title`,item.title)}${s.type==='features'?select('Icon',`item.${i}.icon`,item.icon||'spark',['spark','grid','heart','arrow','check','star']):''}<div class="span-2">${richField(s.type==='faq'?'Answer':'Text',`item.${i}.text`,item.text)}</div>${s.type==='gallery'?imageInput('Image',`item.${i}.image`,item.image)+field('Image description',`item.${i}.alt`,item.alt):''}</div></div>`).join('')}${btn('Add item','add-item','plus')}`:''}<datalist id="media-urls">${state.starters.map(p=>`<option value="${E(p.image)}">${E(p.name)} · sample artwork</option>`).join('')}${state.media.map(m=>`<option value="${E(m.url)}"></option>`).join('')}</datalist></form>`;}
function pageDetails(){return `<section class="panel form-panel"><div class="panel-body"><form id="page-details"><div class="form-grid">${field('Page title','title',page.title)}${select('Content type','kind',page.kind||'page',[['page','Page'],['post','Blog post'],['project','Project'],['service','Service'],['product','Product'],['member','Team member']])}${select('Page layout','starterLayout',page.starterLayout||'',[['','Use site default'],['split','Split hero'],['centered','Centered hero'],['card','Business card'],['resume','Resume'],['editorial','Editorial']])}${field('URL path','slug',page.slug,'text','Leave empty for the homepage. Example: services/web-design')}${select('Publication setting','status',page.status,[['published','Include in next publication'],['draft','Draft — keep private']])}<label class="check" style="margin-top:25px"><input type="checkbox" name="noindex" ${page.seo?.noindex?'checked':''}>Exclude this page from search results</label><div class="span-2">${categoryFields()}${field('Excerpt / summary','excerpt',page.excerpt,'textarea')}${field('Tags (comma separated)','tags',(page.tags||[]).join(', '))}${field('Author / credited name','author',page.author)}${field('Publication date','date',page.date||new Date().toISOString().slice(0,10),'date')}${field('SEO title','seoTitle',page.seo?.title,'text','Leave blank to use the page title and site name.')}${field('Meta description','description',page.seo?.description,'textarea')}${imageInput('Social sharing image','seoImage',page.seo?.image)}</div></div><div class="serp"><small>${E(state.site.url)}/${E(page.slug)}</small><h3>${E(page.seo?.title||page.title+' — '+state.site.name)}</h3><p>${E(page.seo?.description||state.site.description)}</p></div></form><div class="actions" style="margin-top:25px">${btn('Duplicate page','duplicate-page','copy')}${page.slug?btn('Delete page','delete-page','trash','danger'):''}</div></div></section>`;}
function appearance(){return templateLibrary();}
function menuRows(items,path,depth=0){return items.map((item,i)=>{const key=path+'.'+i,top=depth===0&&path==='menus',destination=item.page|| (item.category?'category:'+item.category:'');return `<div class="menu-row"><div class="form-grid"><label>Label<input data-menu="${key}.label" value="${E(item.label)}"></label><label>Destination<select data-menu="${key}.destination"><option value="">Custom link / heading</option><optgroup label="Pages">${state.pages.map(p=>`<option value="${E(p.id)}" ${destination===p.id?'selected':''}>${E(p.title)}</option>`).join('')}</optgroup><optgroup label="Category archives">${state.categories.map(c=>`<option value="category:${E(c.id)}" ${destination==='category:'+c.id?'selected':''}>${E(c.name)}</option>`).join('')}</optgroup></select></label><label>Custom URL<input data-menu="${key}.url" value="${E(item.url)}" placeholder="https:// or /path/"></label></div><label style="margin-top:12px">Short description<input data-menu="${key}.description" value="${E(item.description)}"></label><div class="form-grid menu-options"><label>Icon<select data-menu="${key}.icon">${[['','No icon'],['spark','Spark ✳'],['grid','Grid ▦'],['heart','Heart ♡'],['arrow','Arrow ↗'],['check','Check ✓'],['star','Star ☆']].map(([v,l])=>`<option value="${v}" ${(item.icon||'')===v?'selected':''}>${l}</option>`).join('')}</select></label>${top?`<label>Submenu layout<select data-menu="${key}.layout">${[['auto','Use site default'],['dropdown','Normal dropdown'],['mega','Mega menu']].map(([v,l])=>`<option value="${v}" ${(item.layout||'auto')===v?'selected':''}>${l}</option>`).join('')}</select></label><label>Mega menu columns<select data-menu="${key}.columns">${[2,3,4].map(n=>`<option value="${n}" ${Number(item.columns||3)===n?'selected':''}>${n} columns</option>`).join('')}</select></label>`:''}</div><div class="actions menu-checks">${[['highlight','Show as a button'],['newTab','Open in a new tab'],['nofollow','Mark nofollow']].map(([field,label])=>`<label class="check"><input type="checkbox" data-menu="${key}.${field}" ${item[field]?'checked':''}>${label}</label>`).join('')}</div><div class="menu-tools">${depth<2?btn(top?'Add link or column':'Add child','menu-child','plus','',`data-path="${key}"`):''}${btn('↑','menu-up','','',`data-path="${key}" aria-label="Move menu entry up"`)}${btn('↓','menu-down','','',`data-path="${key}" aria-label="Move menu entry down"`)}${btn('Duplicate','menu-duplicate','copy','',`data-path="${key}"`)}${btn('Remove','menu-remove','trash','danger',`data-path="${key}"`)}</div>${item.children?.length?`<div class="menu-children">${menuRows(item.children,key+'.children',depth+1)}</div>`:''}</div>`;}).join('');}
function navigation(){return heading('Help people find their way.','Shared navigation updates across every page when you publish.',`<span id="save-status"></span>${btn('Save navigation','save-menus','check','primary')}`)+`${chromeDesignPanel()}<section class="panel"><div class="panel-head"><h2>Header behavior</h2></div><div class="panel-body"><div class="form-grid"><label>Default menu style<select data-menu-setting="menuStyle">${[['auto','Automatic — preserve existing menus'],['normal','Normal menus and dropdowns'],['mega','Mega menus']].map(([v,l])=>`<option value="${v}" ${(state.site.menuStyle||'auto')===v?'selected':''}>${l}</option>`).join('')}</select></label><label>Desktop menu alignment<select data-menu-setting="menuAlign"><option value="right" ${state.site.menuAlign!=='center'?'selected':''}>Right</option><option value="center" ${state.site.menuAlign==='center'?'selected':''}>Center</option></select></label></div><div class="actions"><label class="check"><input type="checkbox" data-menu-setting="stickyHeader" ${state.site.stickyHeader?'checked':''}>Keep header visible while scrolling</label><label class="check"><input type="checkbox" data-menu-setting="showSearch" ${state.site.showSearch?'checked':''}>Show website search link</label></div></div></section><div class="notice" style="margin-top:20px">Normal menus use compact dropdowns. Mega menus show 2–4 columns. Add child groups and links to build columns, or use a flat set of links. Each top-level group can override the default. On mobile, both use expandable groups.</div><section class="panel"><div class="panel-head"><h2>Header navigation</h2>${btn('Add link','menu-add','plus','','data-path="menus"')}</div><div class="panel-body">${menuRows(state.site.menus,'menus')||'<p>No header links yet.</p>'}</div></section><section class="panel"><div class="panel-head"><h2>Footer navigation</h2>${btn('Add link','menu-add','plus','','data-path="footerMenus"')}</div><div class="panel-body">${menuRows(state.site.footerMenus,'footerMenus')||'<p>No footer links yet.</p>'}</div></section>`;}
function media(){return heading('A home for your visuals.','Upload once. Use across your whole website.')+`<div class="upload-zone">${I('image')}<h3>Something worth showing.</h3><p>PNG, JPEG, WebP, or GIF · Up to 8 MB per image</p><label class="btn primary" style="display:inline-flex;margin:0;cursor:pointer">${I('plus')}Choose images<input id="media-upload" type="file" accept="image/png,image/jpeg,image/webp,image/gif" multiple hidden style="display:none"></label></div><div class="notice">Original uploads are preserved. Optional local optimization creates a smaller WebP copy in your browser; no files are sent to another service.</div><label class="check"><input type="checkbox" id="optimize-images" checked>Optimize photos locally (maximum 1920 px; keeps the original)</label><label>Find an image<input id="media-search" placeholder="Search names or folders"></label><div class="media-grid">${state.media.filter(m=>!state.media.some(x=>x.originalId===m.id)).map(m=>`<article class="media-card"><img src="${E(m.url)}" alt="Uploaded media" loading="lazy"><div><small>${Math.ceil(m.size/1024)} KB · ${E(m.url.split('.').pop().toUpperCase())}</small><strong style="font-size:11px;display:block">${E(m.name||m.id.slice(0,12))}</strong><small>${E(m.folder||'Unfiled')}</small>${btn('Edit details','media-details','settings','',`data-id="${E(m.id)}"`)}${btn('Copy path','copy-media','copy','',`data-url="${E(m.url)}" style="margin-top:10px"`)}<input value="${E(m.url)}" readonly aria-label="Media path" style="font-size:9px"></div></article>`).join('')||'<div class="empty"><h3>Your collection starts here.</h3><p>Add your first image above.</p></div>'}</div>`;}
function settings(){return heading('The details make it yours.','Your identity, shared header, footer, and contact information.')+`<section class="panel form-panel"><div class="panel-body"><form id="settings-form"><div class="form-grid">${field('Website name','name',state.site.name)}${field('Tagline','tagline',state.site.tagline)}<div class="span-2">${field('Website URL','url',state.site.url,'url','Your public domain, without a path. Used in canonical URLs and your sitemap.')}${field('Default search description','description',state.site.description,'textarea')}</div>${imageInput('Logo image','logo',state.site.logo)}${imageInput('Favicon image','favicon',state.site.favicon)}${imageInput('Default sharing image','socialImage',state.site.socialImage)}${select('Website identity','entity',state.site.entity,['Organization','LocalBusiness','Person'])}${field('Language code','language',state.site.language,'text','For example en, de, ar, or en-US.')}${select('Text direction','direction',state.site.direction,[['ltr','Left to right'],['rtl','Right to left']])}${field('Contact email','email',state.site.email,'email')}${field('Phone','phone',state.site.phone)}<div class="span-2">${field('Address','address',state.site.address,'textarea')}${field('Footer message','footer',state.site.footer)}${field('Copyright name','copyright',state.site.copyright)}${field('Form endpoint (optional)','formEndpoint',state.site.formEndpoint,'url','Leave blank to use the built-in inbox. For externally hosted exports, set a reachable HTTPS form endpoint.')}${field('Social links — one per line: Label | URL','socialLines',state.site.social.map(x=>x.label+' | '+x.url).join('\n'),'textarea')}</div></div><datalist id="media-urls">${state.media.map(m=>`<option value="${E(m.url)}"></option>`).join('')}</datalist><button class="btn primary" type="submit">Save site settings</button></form></div></section>`;}
function seo(){return heading('Make yourself discoverable.','Good foundations for people and search engines.')+`<div class="stats"><div class="stat"><div class="stat-label">Checks to review ${I('search')}</div><strong>${state.warnings.length}</strong><small>Useful guidance, not a ranking score</small></div><div class="stat"><div class="stat-label">Sitemap ${I('page')}</div><strong style="font-size:19px">Automatic</strong><small>Only published, indexable pages</small></div><div class="stat"><div class="stat-label">Structured data ${I('code')}</div><strong style="font-size:19px">${E(state.site.entity)}</strong><small>Generated from your site identity</small></div><div class="stat"><div class="stat-label">Output ${I('globe')}</div><strong style="font-size:19px">Static HTML</strong><small>Content is present without JavaScript</small></div></div><section class="panel readable"><div class="panel-head"><h2>Your pre-publication check</h2>${btn('Site settings','go-settings','settings')}</div><div class="panel-body">${state.warnings.length?`<ul class="warning-list">${state.warnings.map(w=>`<li>${E(w)}</li>`).join('')}</ul>`:'<div class="notice">No issues found by the built-in content checks.</div>'}<p style="font-size:12px">Search visibility also depends on useful original content, relevant links, and real-world performance. These checks do not measure Core Web Vitals or guarantee indexing.</p></div></section><section class="panel readable"><div class="panel-head"><h2>Built in, by default</h2></div><div class="panel-body"><div class="checklist">${['Canonical URLs, page titles, and descriptions','Open Graph and social image metadata','XML sitemap and robots.txt on every publication','Private, authenticated draft previews','Permanent redirects when page URLs change','Semantic headings and accessible navigation'].map(t=>`<div class="checklist-row"><span class="checkmark">✓</span><strong style="font-size:12px">${t}</strong></div>`).join('')}</div><div class="actions" style="margin-top:25px"><a class="btn" href="/sitemap.xml" target="_blank" rel="noopener">View sitemap ↗</a><a class="btn" href="https://search.google.com/search-console" target="_blank" rel="noopener">Google Search Console ↗</a></div></div></section>`;}
function publishing(){return heading('Ready for the world.','Publish a complete snapshot. Your last good website stays live.',btn('Publish now','publish','publish','primary'))+`<div class="notice">Publishing makes saved changes live. Rolling back changes the public website only; your working drafts stay intact.</div><section class="panel"><div class="panel-head"><h2>Publication history</h2><span class="tag">${state.revisions.length} retained</span></div>${schedulePanel()}${state.revisions.map(r=>`<div class="release-row"><div><strong>${date(r.created)} ${r.id===state.current?'<span class="tag">Live</span>':''}</strong><small>Publication ${E(r.id.slice(0,8))}</small></div>${r.id!==state.current?btn('Restore publication','rollback','clock','',`data-id="${E(r.id)}"`):''}</div>`).join('')||'<div class="empty"><h3>Your first publication is ahead.</h3><p>Save your edits, then publish your website.</p></div>'}</section><section class="panel"><div class="panel-head"><h2>Take it with you</h2></div><div class="panel-body"><div class="actions"><a class="btn" href="/api/export">${I('publish')}Download static website ZIP</a><a class="btn" href="/api/backup/full">${I('shield')}Download full backup ZIP</a></div><p style="font-size:11px;margin-top:15px">A full backup includes accounts, content, inbox, original images, optimized copies, and published files. Keep backup archives private. Static exports include assets but require a live form endpoint for submissions.</p></div></section><section class="panel"><div class="panel-head"><h2>URL redirects</h2></div><div class="panel-body">${state.redirects.length?state.redirects.map(r=>`<p style="font-size:12px;margin-bottom:8px"><code>${E(r.from)}</code> → <code>${E(r.to)}</code> <span class="tag neutral">301</span></p>`).join(''):'<p style="font-size:12px">Changing a page URL automatically creates a permanent redirect. Redirect files for Netlify-style hosts and Nginx are included in exports.</p>'}</div></section>`;}
function inbox(){return heading('Good conversations start here.','Messages sent through your website’s built-in contact form.')+`<div class="notice">Messages are stored here. Email notifications are not configured in this release. Set an external form endpoint in Site settings if you need email delivery.</div><section class="panel"><div class="panel-head"><h2>Received messages</h2><span class="tag neutral">Latest ${state.messages.length}</span></div>${state.messages.map(m=>`<article class="message ${m.status==='new'?'new':''}"><div class="message-head"><div><h3>${E(m.name)} ${m.status==='new'?'<span class="tag">New</span>':''}</h3><a href="mailto:${E(m.email)}">${E(m.email)}</a></div><small>${date(m.created)}</small></div><p>${E(m.message)}</p><div class="actions"><a class="btn" href="mailto:${E(m.email)}">Reply by email ↗</a>${btn(m.status==='new'?'Mark read':'Mark unread','message-read','check','',`data-id="${E(m.id)}" data-status="${m.status==='new'?'read':'new'}"`)}${btn('Delete','message-delete','trash','danger',`data-id="${E(m.id)}"`)}</div></article>`).join('')||'<div class="empty"><h3>Room for a hello.</h3><p>New enquiries will appear here.</p></div>'}</section>`;}
function account(){return heading('Your account, protected.','A little care for the keys to your website.')+`<div class="account-grid"><section class="panel"><div class="panel-head"><h2>Change password</h2></div><div class="panel-body"><p style="font-size:11px;margin-bottom:22px">Signed in as ${E(state.user.email)}. Changing your password signs out all your sessions.</p><form id="password-form"><label>Current password<input type="password" name="current" required autocomplete="current-password"></label>${field('New password','password','','password','12–256 characters. Use a unique passphrase.')}${field('Confirm new password','confirm','','password')}<button class="btn primary" type="submit">Update password</button></form></div></section>${state.user.role==='owner'?`<section class="panel"><div class="panel-head"><h2>Your team</h2></div><div class="panel-body"><div id="users-list"><p>Loading accounts…</p></div><h3 style="margin:25px 0 15px">Add a content editor</h3><p style="font-size:11px;margin-bottom:15px">Editors can manage pages, media, and the inbox. Publishing, settings, and accounts are reserved for the owner.</p><form id="user-form">${field('Editor email','email','','email')}${field('Temporary password','password','','password')}<button class="btn" type="submit">Add editor</button></form></div></section>`:''}</div>`;}
async function loadUsers(){if(state.user.role!=='owner')return;try{const users=await api('/users');if($('#users-list'))$('#users-list').innerHTML=users.map(u=>`<div class="release-row" style="padding:12px 0"><div><strong>${E(u.email)}</strong><small>${E(u.role)}</small></div>${u.role==='editor'?btn('Remove','delete-user','trash','danger',`data-id="${E(u.id)}"`):''}</div>`).join('');}catch(e){toast(e.message,true);}}
function setPath(obj,path,value){const parts=path.split('.');let target=obj;for(const k of parts.slice(0,-1))target=target[k];target[parts.at(-1)]=value;}
function getPath(obj,path){return path.split('.').reduce((o,k)=>o[k],obj);}
function captureSection(){const form=$('#section-form');if(!form||!page?.sections[sectionIndex])return;const s=page.sections[sectionIndex];if(s.type==='pricing'){capturePricing(form,s);return;}for(const [key,value]of new FormData(form)){if(key==='hidden')continue;if(key.startsWith('item.')){const [,i,k]=key.split('.');s.items[Number(i)][k]=value;}else s[key]=value;}s.hidden=!!form.elements.hidden.checked;}
function captureDetails(){const form=$('#page-details');if(!form)return;const b=Object.fromEntries(new FormData(form));page.title=b.title;page.slug=b.slug;page.status=b.status;page.kind=b.kind;page.starterLayout=b.starterLayout;page.categories=new FormData(form).getAll('categories');page.tags=(b.tags||'').split(',').map(x=>x.trim()).filter(Boolean);page.excerpt=b.excerpt;page.author=b.author;page.date=b.date;page.seo={title:b.seoTitle,description:b.description,noindex:!!b.noindex,image:b.seoImage};}
async function savePage(){clearTimeout(autosaveTimer);if(saveInFlight)await saveInFlight;captureSection();captureDetails();page=await api('/pages/'+page.id,'PUT',page);dirty=false;autosavePaused=false;await refresh();render();toast('Page saved. Publish when you’re ready.');}
async function saveSite(site=state.site){await api('/site','PUT',site);dirty=false;await refresh();render();toast('Settings saved. Publish to update your website.');}
async function newPage(){if(dirty&&!await confirmAction('Leave without saving?','Your unsaved changes will be discarded.'))return;let slug='new-page',n=1;while(state.pages.some(p=>p.slug===slug))slug='new-page-'+n++;page=await api('/pages','POST',{title:'Untitled page',slug,status:'draft',seo:{},sections:[{id:uid(),type:'hero',title:'Something new starts here.',text:'Make this page your own.'}]});dirty=false;await refresh();view='editor';editTab='details';sectionIndex=0;render();}
app.addEventListener('click',async event=>{const nav=event.target.closest('[data-nav]');if(nav){try{await navigate(nav.dataset.nav);}catch(e){toast(e.message,true);}return;}const tab=event.target.closest('[data-tab]');if(tab){captureSection();captureDetails();editTab=tab.dataset.tab;render();return;}const button=event.target.closest('[data-action]');if(!button||busy)return;event.preventDefault();const a=button.dataset.action;try{
  if(await extraAction(a,button))return;
  if(a==='mobile'){$('.sidebar').classList.toggle('open');return;}
  if(a.startsWith('go-')){await navigate(a.slice(3));return;}
  if(a==='logout'){if(dirty&&!await confirmAction('Sign out without saving?','Unsaved changes will be discarded.'))return;await api('/logout','POST',{});state=null;dirty=false;authView();return;}
  if(a==='new-page'){await newPage();return;}
  if(a==='edit'){autosavePaused=false;if(dirty&&!await confirmAction('Leave without saving?','Unsaved changes will be discarded.'))return;page=structuredClone(state.pages.find(p=>p.id===button.dataset.id));sectionIndex=0;editTab='content';view='editor';dirty=false;render();return;}
  if(a==='back-pages'){await navigate('pages');return;}
  if(a==='save-page'){busy=true;await savePage();return;}
  if(a==='publish'){if(saveInFlight)await saveInFlight;if(dirty){toast('Save your current edits before publishing.',true);return;}if(!await confirmAction('Publish your website?','All saved pages marked for publication, settings, and navigation will go live together.'))return;busy=true;button.disabled=true;button.textContent='Publishing…';await api('/publish','POST',{});await refresh();render();toast('Your website is live.');return;}
  if(a==='rollback'){if(!await confirmAction('Restore this publication?','The public website will use this snapshot. Your current drafts will be preserved.'))return;busy=true;await api('/rollback','POST',{id:button.dataset.id});await refresh();render();toast('Previous publication restored.');return;}
  if(a==='theme'){if(state.site.theme===button.dataset.theme)return;if(!await confirmAction('Change your theme?','Your pages and navigation will be preserved. The recommended palette is applied only when its checkbox is enabled. Publish when you are ready to make the look live.'))return;const theme=state.themes.find(t=>t.id===button.dataset.theme);const palette=$('#apply-theme-palette')?.checked;await saveSite({...state.site,theme:theme.id,...(palette?{accent:theme.accent,font:theme.font}:{})});return;}
  if(a==='section'){captureSection();sectionIndex=Number(button.dataset.index);render();return;}
  if(['section-up','section-down'].includes(a)){captureSection();const i=Number(button.dataset.index),next=i+(a==='section-up'?-1:1);if(next<0||next>=page.sections.length)return;[page.sections[i],page.sections[next]]=[page.sections[next],page.sections[i]];sectionIndex=next;markDirty();render();return;}
  if(a==='add-section'){captureSection();const type=$('[name="new-section-type"]').value;page.sections.push({id:uid(),type,title:type==='contact'?'Get in touch':'Your heading here',text:'',items:[],...(type==='pricing'?{pricing:newPricing()}:{} )});sectionIndex=page.sections.length-1;markDirty();render();return;}
  if(a==='duplicate-section'){captureSection();const s=structuredClone(page.sections[sectionIndex]);s.id=uid();page.sections.splice(sectionIndex+1,0,s);sectionIndex++;markDirty();render();return;}
  if(a==='remove-section'){if(!await confirmAction('Remove this section?','Save the page to keep this change.'))return;page.sections.splice(sectionIndex,1);sectionIndex=Math.max(0,sectionIndex-1);markDirty();render();return;}
  if(a==='add-item'){captureSection();const s=page.sections[sectionIndex];s.items??=[];s.items.push({title:'New item',text:'',icon:'spark'});markDirty();render();return;}
  if(a==='remove-item'){captureSection();page.sections[sectionIndex].items.splice(Number(button.dataset.index),1);markDirty();render();return;}
  if(a==='item-up'){captureSection();const i=Number(button.dataset.index);if(i>0){const items=page.sections[sectionIndex].items;[items[i-1],items[i]]=[items[i],items[i-1]];markDirty();render();}return;}
  if(a==='duplicate-page'){captureDetails();captureSection();let slug=(page.slug||'home')+'-copy';let n=1;while(state.pages.some(p=>p.slug===slug))slug=(page.slug||'home')+'-copy-'+n++;page=await api('/pages','POST',{...page,title:page.title+' (copy)',slug,status:'draft'});dirty=false;await refresh();render();toast('Page duplicated as a draft.');return;}
  if(a==='delete-page'){if(!await confirmAction('Delete this page?','The page will move to recoverable trash. The public page remains until your next publication.'))return;await api('/pages/'+page.id,'DELETE');dirty=false;await navigate('pages');toast('Page deleted.');return;}
  if(a==='save-menus'){await saveSite();return;}
  if(a==='menu-add'){getPath(state.site,button.dataset.path).push({id:uid(),label:'New link',page:'',url:'',children:[]});markDirty();render();return;}
  if(a==='menu-child'){const parent=getPath(state.site,button.dataset.path);parent.children??=[];parent.children.push({id:uid(),label:'New link',page:'',url:'',children:[]});markDirty();render();return;}
  if(a==='menu-remove'||a==='menu-up'){const parts=button.dataset.path.split('.'),i=Number(parts.pop()),list=getPath(state.site,parts.join('.'));if(a==='menu-remove')list.splice(i,1);else if(i>0)[list[i-1],list[i]]=[list[i],list[i-1]];markDirty();render();return;}
  if(a==='copy-media'){try{await navigator.clipboard.writeText(button.dataset.url);toast('Media path copied.');}catch{button.parentElement.querySelector('input').select();toast('Select and copy the media path.');}return;}
  if(a==='message-read'){await api('/messages','PATCH',{id:button.dataset.id,status:button.dataset.status});await refresh();render();return;}
  if(a==='message-delete'){if(!await confirmAction('Delete this message?','This permanently removes the message from the inbox.'))return;await api('/messages','DELETE',{id:button.dataset.id});await refresh();render();return;}
  if(a==='delete-user'){if(!await confirmAction('Remove this editor?','Their account and sessions will be removed.'))return;await api('/users/'+button.dataset.id,'DELETE');await loadUsers();toast('Editor removed.');return;}
}catch(e){toast(e.message,true);}finally{busy=false;if(button.isConnected)button.disabled=false;}});
app.addEventListener('input',event=>{const el=event.target;if(el.id==='page-search'){$('#page-rows').innerHTML=pageRows(filteredPages());return;}if(el.dataset.menu){updateMenuField(el);markDirty();return;}if(el.closest('#section-form')){captureSection();markDirty();}else if(el.closest('#page-details')){captureDetails();markDirty();}else if(el.closest('#settings-form,#appearance-form'))markDirty();});
app.addEventListener('change',async event=>{const el=event.target;if(el.dataset.menu){updateMenuField(el);markDirty();}if(el.id==='media-upload'){try{for(const file of el.files){if(file.size>8*1024*1024)throw new Error('Each image must be smaller than 8 MB.');await uploadImage(file);}await refresh();render();toast('Images uploaded.');}catch(e){toast(e.message,true);} }});
app.addEventListener('submit',async event=>{if(event.target.id?.startsWith('php-'))return;event.preventDefault();const form=event.target,b=Object.fromEntries(new FormData(form));const submit=form.querySelector('[type="submit"]');if(submit)submit.disabled=true;try{
 if(await extraSubmit(form,b))return;
 if(form.getAttribute('id')==='auth-form'){const result=await api(authMode==='setup'?'/setup':'/login','POST',b);if(result.mfaRequired){phpMfaChallenge=result.challenge;authView();return;}if(authMode==='setup'){authMode='login';authView();toast('Installation complete. Sign in to your new studio.');}else{await refresh();view='dashboard';render();}return;}
 if(form.getAttribute('id')==='settings-form'){const social=b.socialLines.split('\n').filter(x=>x.trim()).map(line=>{const i=line.indexOf('|');if(i<0)throw new Error('Use Label | https://example.com for each social link.');return {label:line.slice(0,i).trim(),url:line.slice(i+1).trim()};});delete b.socialLines;await saveSite({...state.site,...b,social});return;}
 if(form.getAttribute('id')==='appearance-form'){await saveSite({...state.site,...b,bundledArtwork:form.elements.bundledArtwork.checked});return;}
 if(form.getAttribute('id')==='password-form'){if(b.password!==b.confirm)throw new Error('The new passwords do not match.');await api('/password','POST',b);state=null;dirty=false;authView();toast('Password changed. Sign in again.');return;}
 if(form.getAttribute('id')==='user-form'){await api('/users','POST',b);form.reset();await loadUsers();toast('Editor created. Share their temporary password securely.');return;}
 if(form.getAttribute('id')==='section-form'||form.getAttribute('id')==='page-details'){await savePage();return;}
}catch(e){if(form.getAttribute('id')==='auth-form'){const values=Object.fromEntries(new FormData(form));authView(e.message);for(const name of ['email','token','name','url','preset'])if(values[name]&&$(`[name="${name}"]`))$(`[name="${name}"]`).value=values[name];}else toast(e.message,true);}finally{if(submit?.isConnected)submit.disabled=false;}});
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
document.addEventListener('keydown',async e=>{if((e.ctrlKey||e.metaKey)&&e.key==='s'){e.preventDefault();try{if(view==='editor')await savePage();else if(view==='navigation')await saveSite();else $('#settings-form button[type=submit],#appearance-form button[type=submit]')?.click();}catch(error){toast(error.message,true);}}});
(async()=>{try{const status=await api('/status');availableStarters=status.starters||[];authMode=status.configured?'login':'setup';if(status.configured){try{await refresh();render();return;}catch{}}authView();}catch(e){app.innerHTML=`<div class="loading"><h1>We couldn’t open your studio.</h1><p>${E(e.message)}</p><a class="btn" href="/admin/">Try again</a></div>`;}})();
function filteredPages(){const q=($('#page-search')?.value||'').toLowerCase(),kind=$('#kind-filter')?.value||'',category=$('#category-filter')?.value||'';return state.pages.filter(p=>(!kind||(p.kind||'page')===kind)&&(!category||p.categories?.includes(category))&&(p.title+' '+p.slug+' '+(p.tags||[]).join(' ')).toLowerCase().includes(q));}
function categoryFields(){return `<fieldset class="category-choices"><legend>Categories</legend>${state.categories.length?state.categories.map(c=>`<label class="check"><input type="checkbox" name="categories" value="${E(c.id)}" ${page.categories?.includes(c.id)?'checked':''}>${E(c.name)}</label>`).join(''):'<p>Create categories in the Categories screen, then assign them here.</p>'}</fieldset>`;}
function richField(label,name,value){return `<label>${E(label)}<span class="format-toolbar" role="group" aria-label="Text formatting">${[['bold','Bold'],['italic','Italic'],['link','Link'],['list','List'],['quote','Quote'],['table','Table'],['code','Code']].map(([type,title])=>btn(title,'format-text','','',`data-target="${E(name)}" data-format="${type}"`)).join('')}</span><textarea name="${E(name)}" rows="7">${E(value)}</textarea><small>Formatting uses readable Markdown. Blank lines make paragraphs. Raw HTML is safely escaped.</small></label>`;}
function categoryScreen(){return heading('A place for every subject.','Organize content and links with reusable categories.',btn('Add category','category-new','plus','primary'))+`<section class="panel"><div class="panel-head"><h2>Categories</h2><span class="tag neutral">${state.categories.length}</span></div>${state.categories.map(c=>`<div class="release-row"><div><strong>${E(c.name)}</strong><small>/category/${E(c.slug)}/ · ${state.pages.filter(p=>p.categories?.includes(c.id)).length} content items</small><p style="font-size:11px">${E(c.description)}</p></div><div class="actions">${btn('Edit','category-edit','','',`data-id="${E(c.id)}"`)}${btn('Remove','category-remove','trash','danger',`data-id="${E(c.id)}"`)}</div></div>`).join('')||'<div class="empty"><h3>Give your content some structure.</h3><p>Add a category such as News, Design, or Resources.</p></div>'}</section><div class="notice" style="margin-top:20px">Category archives are generated when you publish. Renaming a category URL creates a redirect. Assigned categories cannot be deleted accidentally.</div>`;}
function linkScreen(){return heading('Good links, all together.','A reusable directory for useful resources and internal destinations.',btn('Add a link','link-new','plus','primary'))+`<section class="panel"><div class="panel-head"><h2>Saved links</h2><span class="tag neutral">${state.links.length}</span></div>${state.links.map(l=>`<div class="release-row"><div><strong>${E(l.label)}</strong><small>${E(l.page?state.pages.find(p=>p.id===l.page)?.title||'Missing page':l.url)}${l.category?' · '+E(state.categories.find(c=>c.id===l.category)?.name||''):''}</small><p style="font-size:11px">${E(l.description)}</p></div><div class="actions">${btn('Edit','link-edit','','',`data-id="${E(l.id)}"`)}${btn('Remove','link-remove','trash','danger',`data-id="${E(l.id)}"`)}</div></div>`).join('')||'<div class="empty"><h3>Keep useful things within reach.</h3><p>Add a resource, partner website, or internal page link.</p></div>'}</section><div class="notice" style="margin-top:20px">Add a “links” section to any page to display saved links, optionally filtered by category. External links are not fetched by the checker; it makes no outside network requests.</div><section class="panel"><div class="panel-head"><h2>Internal link health</h2>${btn('Check links','check-links','search')}</div><div class="panel-body" id="link-report">Checking saved references…</div></section>`;}
async function loadLinkCheck(){try{const results=await api('/link-check');if($('#link-report'))$('#link-report').innerHTML=results.length?results.map(r=>`<div class="link-result"><span class="tag ${r.level==='error'?'draft':'neutral'}">${E(r.level)}</span><strong>${E(r.source)}</strong><p>${E(r.message)}</p></div>`).join(''):'<div class="notice">No broken internal destinations or orphan pages found.</div>';}catch(e){toast(e.message,true);}}
function trashScreen(){return heading('A second chance.','Deleted content stays here until you choose to remove it permanently.')+`<section class="panel"><div class="panel-head"><h2>Recoverable content</h2><span class="tag neutral">${state.trash.length}</span></div>${state.trash.map(t=>`<div class="release-row"><div><strong>${E(t.snapshot.title)}</strong><small>Deleted ${date(t.created)} · /${E(t.snapshot.slug)}/</small></div><div class="actions">${btn('Restore as draft','trash-restore','clock','',`data-id="${E(t.id)}"`)}${state.user.role==='owner'?btn('Delete permanently','trash-purge','trash','danger',`data-id="${E(t.id)}"`):''}</div></div>`).join('')||'<div class="empty"><h3>Nothing lost.</h3><p>Pages moved to trash will appear here.</p></div>'}</section>`;}
function maintenanceScreen(){return heading('Built to grow with you.','Update the application. Keep everything you created.')+`<div class="stats"><div class="stat"><div class="stat-label">Installed release ${I('code')}</div><strong>${E(state.version)}</strong><small>1DED Free CMS</small></div><div class="stat"><div class="stat-label">Database schema ${I('shield')}</div><strong>${state.schema}</strong><small>Automatic migration backups</small></div><div class="stat"><div class="stat-label">Stored images ${I('image')}</div><strong>${state.media.length}</strong><small>Originals and optimized copies</small></div><div class="stat"><div class="stat-label">Required services ${I('globe')}</div><strong>0</strong><small>No cloud account required</small></div></div><section class="panel readable"><div class="panel-head"><h2>Your data stays yours</h2></div><div class="panel-body"><div class="notice">Official release packages contain application code only. The updater preserves your data directory, images, accounts, content, publications, and .env configuration. It creates a full recovery backup before replacing code.</div><ol class="instructions"><li>Download a release ZIP from the project’s trusted GitHub Releases page and verify its published SHA-256 checksum.</li><li>Stop the CMS service. Keep the same DATA_DIR or Docker volume.</li><li>From the installed project folder, run:<pre><code>node cli.mjs update /path/to/1DED-Free-CMS-new.zip</code></pre></li><li>Restart the service. Any schema migration first saves a database backup.</li></ol><p style="font-size:12px">The updater rejects corrupted packages, unsafe paths, incompatible schemas, and downgrades. It does not download code automatically or require a third-party update service. See docs/UPGRADING.md for the first upgrade from 0.1.0 and Docker instructions.</p></div></section><section class="panel readable"><div class="panel-head"><h2>Back up everything</h2></div><div class="panel-body"><a class="btn primary" href="/api/backup/full">${I('shield')}Download full backup ZIP</a><p style="font-size:12px;margin-top:15px">Includes database, original images, optimized images, and publications. Keep it private. For large sites, use the command-line backup to avoid browser memory limits.</p><pre><code>node cli.mjs backup /path/to/new-backup-folder</code></pre><h3 style="margin-top:25px">Restore a full backup</h3><p style="font-size:12px;margin-top:10px">Stop the CMS, then run this command. Your current data is backed up before restoration. Database-only downloads are not full backups.</p><pre><code>node cli.mjs restore /path/to/1ded-full-backup.zip</code></pre><p style="font-size:12px">Restart afterward. Application code is updated separately; restoration never silently downgrades your installation.</p></div></section>`;}
function schedulePanel(){const schedule=state.schedule;return `<div class="panel-body" style="border-bottom:1px solid var(--line)"><h3>Schedule a publication</h3><p style="font-size:11px;margin:8px 0 15px">Publish all saved eligible content at a chosen time. The server must be running; overdue jobs run after restart. Changes saved before that time will be included.</p>${schedule?`<div class="notice">${E(schedule.status)} · ${date(schedule.at)}${schedule.error?' · '+E(schedule.error):''}</div>`:''}<form id="schedule-form"><div class="actions"><label style="margin:0">Your local time<input type="datetime-local" name="at" required></label><button type="submit" class="btn">Schedule</button>${schedule?.status==='pending'?btn('Cancel schedule','cancel-schedule'):''}</div></form></div>`;}
async function loadHistory(){try{const rows=await api('/history/'+page.id);if($('#history-list'))$('#history-list').innerHTML=rows.map(r=>`<div class="release-row"><div><strong>${date(r.created)}</strong><small>${E(r.actor)} · ${E(r.snapshot.title)}</small><p style="font-size:11px">${E(r.snapshot.sections?.[0]?.title||'')}</p></div>${btn('Restore this version','history-restore','clock','',`data-id="${E(r.id)}"`)}</div>`).join('')||'<p>Your earlier saved versions will appear here. Up to 50 versions are retained per page.</p>';}catch(e){toast(e.message,true);}}
function openEditor(title,html,id){$('#item-dialog')?.remove();const dialog=document.createElement('dialog');dialog.id='item-dialog';dialog.innerHTML=`<div class="panel-head"><h2>${E(title)}</h2>${btn('Close','dialog-close')}</div><form id="${id}" class="panel-body">${html}<button type="submit" class="btn primary">Save changes</button></form>`;app.append(dialog);dialog.showModal();}
function categoryEditor(c={}){openEditor(c.id?'Edit category':'New category',`<input type="hidden" name="id" value="${E(c.id)}"><input type="hidden" name="revision" value="${E(c.revision)}">${field('Category name','name',c.name)}${field('URL slug','slug',c.slug,'text','Lowercase letters, numbers, and hyphens.')}${field('Description','description',c.description,'textarea')}`,'category-form');}
function linkEditor(l={}){openEditor(l.id?'Edit saved link':'New saved link',`<input type="hidden" name="id" value="${E(l.id)}"><input type="hidden" name="revision" value="${E(l.revision)}">${field('Link label','label',l.label)}${select('Destination page','page',l.page||'',[['','Use custom URL'],...state.pages.map(p=>[p.id,p.title])])}${field('Custom destination URL','url',l.url,'text','Page selection takes priority. Custom links may use https://, /path/, mailto:, or tel:.')}${select('Category','category',l.category||'',[['','Uncategorized'],...state.categories.map(c=>[c.id,c.name])])}${field('Description','description',l.description,'textarea')}${['newTab','nofollow','sponsored'].map(k=>`<label class="check"><input type="checkbox" name="${k}" ${l[k]?'checked':''}>${{newTab:'Open in a new tab',nofollow:'Mark nofollow',sponsored:'Mark sponsored'}[k]}</label>`).join('')}`,'link-form');}
async function extraAction(a,b){
 if(a.startsWith('pricing-')){captureSection();const plans=page.sections[sectionIndex].pricing.plans,index=Number(b.dataset.index);if(a==='pricing-add'){if(plans.length>=12){toast('A pricing section supports up to 12 plans.',true);return true;}plans.push(newPlan('New plan'));}else if(a==='pricing-remove')plans.splice(index,1);else if(a==='pricing-copy'){if(plans.length>=12)return true;plans.splice(index+1,0,structuredClone(plans[index]));}else if(a==='pricing-up'&&index>0)[plans[index-1],plans[index]]=[plans[index],plans[index-1]];else if(a==='pricing-down'&&index<plans.length-1)[plans[index+1],plans[index]]=[plans[index],plans[index+1]];markDirty();render();return true;}

 if(a==='starter-artwork'){const record=state.starterImports.find(r=>r.id===b.dataset.id);if(!await confirmAction('Add pictures to this template’s existing pages?','Fill empty hero, image and gallery slots with related bundled artwork. Your own images, text, URLs and publication status are preserved. Earlier versions are kept in page history.'))return true;const revisions=Object.fromEntries(state.pages.filter(p=>record.pageIds.includes(p.id)).map(p=>[p.id,p.revision]));const result=await api('/starters/artwork','POST',{id:record.id,revisions});await refresh();render();toast(result.count+' pages refreshed. Preview before publishing.');return true;}

 if(a==='starter-import'){const starter=state.starters.find(p=>p.id===b.dataset.id);openEditor('Add '+starter.name+' pages',`<input type="hidden" name="starterId" value="${E(starter.id)}"><input type="hidden" name="revision" value="${E(state.site.revision)}"><div class="notice">Adds ${starter.pages.length+(starter.hasPosts?2:0)} editable draft pages. Existing pages, uploads, and categories are preserved. Nothing is published automatically.</div>${field('Destination folder','prefix',starter.id,'text','Use a unique lowercase folder name. Example: '+starter.id+' → /'+starter.id+'/')}<label class="check"><input type="checkbox" name="addMenu" checked>Add a navigation group for the new pages</label><label class="check"><input type="checkbox" name="applyLook">Apply the recommended colors and typography to the whole site</label><p style="font-size:11px">Review all example copy and replace placeholder details before publishing. Global appearance stays unchanged unless you enable the checkbox above.</p>`,'starter-import-form');return true;}
 if(a==='starter-activate'){if(!await confirmAction('Include these pages in the next publication?','Review and replace all starter examples first. This changes the imported pages from private drafts to eligible pages; it does not publish them immediately.'))return true;await api('/starters/activate','POST',{id:b.dataset.id});await refresh();render();toast('Imported pages are included in the next publication.');return true;}

 if(a==='menu-down'||a==='menu-duplicate'){const parts=b.dataset.path.split('.'),index=Number(parts.pop()),list=getPath(state.site,parts.join('.'));if(a==='menu-down'&&index<list.length-1)[list[index],list[index+1]]=[list[index+1],list[index]];if(a==='menu-duplicate'){const copy=structuredClone(list[index]);const rekey=item=>{item.id=uid();(item.children||[]).forEach(rekey);};rekey(copy);list.splice(index+1,0,copy);}markDirty();render();return true;}

 if(a==='dialog-close'){$('#item-dialog').close();return true;}
 if(a==='category-new'){categoryEditor();return true;}if(a==='category-edit'){categoryEditor(state.categories.find(c=>c.id===b.dataset.id));return true;}
 if(a==='link-new'){linkEditor();return true;}if(a==='link-edit'){linkEditor(state.links.find(l=>l.id===b.dataset.id));return true;}
 if(a==='category-remove'||a==='link-remove'){if(!await confirmAction('Remove this item?','Categories still assigned to content cannot be removed. Your published website stays unchanged until you publish again.'))return true;await api('/'+(a==='category-remove'?'categories':'links')+'/'+b.dataset.id,'DELETE');await refresh();render();toast('Item removed.');return true;}
 if(a==='check-links'){await loadLinkCheck();return true;}
 if(a==='trash-restore'){await api('/trash/'+b.dataset.id,'POST',{});await refresh();render();toast('Content restored as a draft.');return true;}
 if(a==='trash-purge'){if(!await confirmAction('Permanently delete this content?','This removes it from the trash. You will need a backup to recover it.'))return true;await api('/trash/'+b.dataset.id,'DELETE');await refresh();render();toast('Trashed content permanently removed.');return true;}
 if(a==='history-restore'){if(saveInFlight)await saveInFlight;if(!await confirmAction('Restore this saved version?','Your current saved content is added to history first. The public website does not change until publication.'))return true;page=await api('/history/'+page.id,'POST',{id:b.dataset.id,revision:page.revision});dirty=false;await refresh();editTab='content';sectionIndex=0;render();toast('Earlier content restored. Current URL preserved.');return true;}
 if(a==='cancel-schedule'){await api('/schedule','PUT',{});await refresh();render();return true;}
 if(a==='format-text'){const field=Array.from($('#section-form').elements).find(el=>el.name===b.dataset.target);const selected=field.value.slice(field.selectionStart,field.selectionEnd)||'your text';const snippets={bold:'**'+selected+'**',italic:'*'+selected+'*',link:'['+selected+'](https://example.com)',list:'\n- '+selected+'\n- Another item\n',quote:'\n> '+selected+'\n',table:'\n| Heading | Heading |\n| --- | --- |\n| Cell | Cell |\n',code:'`'+selected+'`'};field.setRangeText(snippets[b.dataset.format],field.selectionStart,field.selectionEnd,'select');field.focus();captureSection();markDirty();return true;}
 if(a==='media-details'){const m=state.media.find(x=>x.id===b.dataset.id);openEditor('Image details',`<input type="hidden" name="id" value="${E(m.id)}"><img src="${E(m.url)}" alt="" style="width:100%;max-height:180px;object-fit:contain;margin-bottom:20px">${field('Image name','name',m.name||'')}${field('Default image description','alt',m.alt||'')}${field('Folder / group','folder',m.folder||'')}${m.sourceUrl?`<p><a href="${E(m.sourceUrl)}" download>Download uploaded original ↗</a></p>`:""}${m.originalId?`<p><a href="/media/${E(m.originalId)}" download>Download preserved original ↗</a></p>`:''}`,'media-details-form');return true;}
 return false;
}
async function extraSubmit(form,b){
 if(form.getAttribute('id')==='starter-import-form'){b.addMenu=form.elements.addMenu.checked;b.applyLook=form.elements.applyLook.checked;const result=await api('/starters/import','POST',b);await refresh();render();toast('Added '+result.import.pageIds.length+' draft pages under /'+result.import.prefix+'/.');return true;}

 if(form.getAttribute('id')==='category-form'||form.getAttribute('id')==='link-form'){const key=form.getAttribute('id')==='category-form'?'categories':'links';for(const k of ['newTab','nofollow','sponsored'])b[k]=form.elements[k]?.checked||false;await api('/'+key+(b.id?'/'+b.id:''),b.id?'PUT':'POST',b);await refresh();render();toast('Saved. Publish to update the public website.');return true;}
 if(form.getAttribute('id')==='schedule-form'){const date=new Date(b.at);await api('/schedule','PUT',{at:date.toISOString()});await refresh();render();toast('Publication scheduled.');return true;}
 if(form.getAttribute('id')==='media-details-form'){await api('/media','PATCH',b);await refresh();render();toast('Image details saved.');return true;}
 return false;
}
function queueAutosave(){if(view!=='editor'||autosavePaused)return;clearTimeout(autosaveTimer);autosaveTimer=setTimeout(autoSave,1800);}
async function autoSave(){if(!page||view!=='editor'||!dirty||autosavePaused)return;if(saveInFlight){queueAutosave();return;}captureSection();captureDetails();const outgoing=structuredClone(page),generation=editGeneration;const status=$('#save-status');if(status)status.textContent='Saving automatically…';
 saveInFlight=(async()=>{try{const result=await api('/pages/'+outgoing.id,'PUT',outgoing);state.pages=state.pages.map(p=>p.id===result.id?result:p);if(page?.id===result.id){page.revision=result.revision;page.updatedAt=result.updatedAt;if(generation===editGeneration){dirty=false;const label=$('#save-status');if(label){label.textContent='Saved automatically';label.className='';}}else queueAutosave();}}catch(error){autosavePaused=true;toast('Autosave paused: '+error.message,true);const label=$('#save-status');if(label)label.textContent='Not saved — review the error';}finally{saveInFlight=null;}})();await saveInFlight;
}
async function uploadImage(file){const original=await api('/media','POST',file);await api('/media','PATCH',{id:original.id,name:file.name});if(!$('#optimize-images')?.checked||!['image/jpeg','image/png','image/webp'].includes(file.type))return;let bitmap;try{bitmap=await createImageBitmap(file);if(bitmap.width*bitmap.height>40000000)throw new Error('Image is too large to optimize safely.');const scale=Math.min(1,1920/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/webp',.82));if(blob&&blob.size<file.size){const optimized=await api('/media','POST',blob);await api('/media','PATCH',{id:optimized.id,name:file.name.replace(/\.[^.]+$/,'')+' (optimized)',originalId:original.id,width:canvas.width,height:canvas.height});}}catch(error){toast('Original preserved; optimization skipped: '+error.message,true);}finally{bitmap?.close();}}
app.addEventListener('change',e=>{if(['kind-filter','category-filter'].includes(e.target.id))$('#page-rows').innerHTML=pageRows(filteredPages());if(view==='editor'&&e.target.name==='image'){const media=state.media.find(m=>m.url===e.target.value),alt=$('#section-form [name="alt"]');if(alt&&!alt.value&&media?.alt){alt.value=media.alt;captureSection();markDirty();}}});
app.addEventListener('input',e=>{if(e.target.id==='media-search'){const q=e.target.value.toLowerCase();document.querySelectorAll('.media-card').forEach(card=>card.hidden=!card.textContent.toLowerCase().includes(q));}});

function updateMenuField(el){const parts=el.dataset.menu.split('.'),field=parts.pop(),item=getPath(state.site,parts.join('.'));if(field==='destination'){const category=el.value.startsWith('category:');item.page=category?'':el.value;item.category=category?el.value.slice(9):'';}else item[field]=el.type==='checkbox'?el.checked:el.value;}
app.addEventListener('input',e=>{if(e.target.dataset.menuSetting){state.site[e.target.dataset.menuSetting]=e.target.type==='checkbox'?e.target.checked:e.target.value;markDirty();}});
app.addEventListener('change',e=>{if(e.target.dataset.menuSetting){state.site[e.target.dataset.menuSetting]=e.target.type==='checkbox'?e.target.checked:e.target.value;markDirty();}if(e.target.id==='apply-theme-palette'){document.querySelectorAll('[data-theme-preview]').forEach(a=>a.href='/preview/'+encodeURIComponent(a.dataset.page)+'?theme='+encodeURIComponent(a.dataset.themePreview)+(e.target.checked?'&palette=preset':''));}});


function libraryMatch(name,group,kind){const q=($('#template-search')?.value||'').toLowerCase(),category=$('#template-category')?.value||'',type=$('#template-type')?.value||'';return (!q||name.toLowerCase().includes(q))&&(!category||category===group)&&(!type||type===kind);}
function starterCards(){return state.starters.filter(p=>libraryMatch(p.name+' '+p.description,p.group,'subject')).map(p=>`<article class="theme-card starter-card"><div class="template-photo"><img src="${E(p.image)}" alt="${E(p.alt)}" loading="lazy" width="1536" height="1024"><span class="photo-label">${E(p.group)} · Subject template</span><div class="photo-title">${E(p.name)}</div></div><div class="panel-body"><h3>${E(p.name)}</h3><p class="starter-description">${E(p.description)}</p><p class="starter-pages">${E(p.pages.join(' · '))}${p.hasPosts?' · 2 sample articles':''}</p><small>${p.pages.length+(p.hasPosts?2:0)} pages · ${E(p.menuStyle)} menu · ${E(p.theme)} palette</small></div><div class="theme-card-actions"><a class="btn" href="/starter-preview/${E(p.id)}/home" target="_blank" rel="noopener">Preview website ↗</a>${btn('Add draft pages','starter-import','plus','',`data-id="${E(p.id)}"`)}</div></article>`).join('');}
function visualThemeCards(){const home=state.pages.find(p=>p.slug==='')||state.pages[0];return state.themes.filter(t=>libraryMatch(t.name+' '+t.description+' '+t.bestFor,'Visual themes','theme')).map(t=>`<article class="theme-card ${state.site.theme===t.id?'selected':''}"><div class="theme-art ${E(t.id)}"><div class="theme-mock" style="--preview-accent:${E(t.accent)}"><small>VISUAL THEME · ${E(t.bestFor)}</small><h3>${E(t.headline).replace(/\n/g,'<br>')}</h3><span></span></div></div><div class="panel-body"><span class="tag neutral">Visual theme</span><h3>${E(t.name)} ${state.site.theme===t.id?'✓':''}</h3><p>${E(t.description)}</p><small>Restyle your existing pages</small></div><div class="theme-card-actions">${home?`<a class="btn" href="/preview/${E(home.id)}?theme=${E(t.id)}&palette=preset" data-theme-preview="${E(t.id)}" data-page="${E(home.id)}" target="_blank" rel="noopener">Preview on my site ↗</a>`:''}${btn(state.site.theme===t.id?'Selected':'Use theme','theme','','',`data-theme="${E(t.id)}"`)}</div></article>`).join('');}
function libraryCards(){const cards=starterCards()+visualThemeCards();return cards||'<div class="empty"><h3>No matching designs</h3><p>Clear the search or choose all categories.</p></div>';}
function templateLibrary(){return heading('Find your website’s personality.','All 23 designs in one place. Fifteen image-rich subject templates and eight visual themes.')+`<div class="library-intro"><div><strong>A whole website, or a fresh coat of colour.</strong><p>Subject templates add editable draft pages. Visual themes restyle your current content. Preview any design before choosing.</p></div><span>15 subjects + 8 themes</span></div><section class="panel library-controls"><div class="panel-body starter-filters"><label>Search all designs<input id="template-search" type="search" placeholder="Food, creative, minimal, hosting…"></label><label>Design type<select id="template-type"><option value="">All 23 designs</option value="subject">Subject templates</option><option value="theme">Visual themes</option></select></label><label>Category<select id="template-category"><option value="">All categories</option>${[...new Set(state.starters.map(p=>p.group)),'Visual themes'].map(g=>`<option value="${E(g)}">${E(g)}</option>`).join('')}</select></label></div><div class="library-settings"><label class="check"><input type="checkbox" id="apply-theme-palette" checked>Use the theme’s recommended colours and typography when switching</label><p>Bundled imagery is AI-generated sample artwork. Replace it with your own images where authenticity matters.</p></div></section><div class="theme-grid template-library" id="template-cards">${libraryCards()}</div><section class="panel form-panel" style="margin-top:25px"><div class="panel-head"><h2>Fine-tune your current design</h2></div><div class="panel-body"><form id="appearance-form"><label class="check"><input type="checkbox" name="bundledArtwork" ${state.site.bundledArtwork!==false?'checked':''}>Show related sample pictures in empty hero sections</label><div class="form-grid">${field('Accent color','accent',state.site.accent,'color')}${select('Typography','font',state.site.font,[['sans','Modern sans serif'],['serif','Classic serif'],['mono','Monospace']])}</div><button class="btn primary" type="submit">Save appearance</button></form></div></section>${recentImports()}`;}
function recentImports(){return state.starterImports.length?`<section class="panel" style="margin-top:25px"><div class="panel-head"><h2>Recently added templates</h2></div>${state.starterImports.slice(0,10).map(record=>{const pages=state.pages.filter(p=>record.pageIds.includes(p.id)),drafts=pages.filter(p=>p.status==='draft').length;return `<div class="release-row"><div><strong>${E(record.name)}</strong><small>/${E(record.prefix)}/ · ${pages.length} pages · ${drafts} drafts</small></div><div class="actions">${pages[0]?btn('Edit home','edit','page','',`data-id="${E(pages[0].id)}"`):''}${btn('Refresh page pictures','starter-artwork','image','',`data-id="${E(record.id)}"`)}${drafts?btn('Include in next publish','starter-activate','check','',`data-id="${E(record.id)}"`):''}</div></div>`;}).join('')}</section>`:'';}
function starterScreen(){return templateLibrary();}
function filterLibrary(){const grid=$('#template-cards');if(grid){grid.innerHTML=libraryCards();if(!$('#apply-theme-palette').checked)grid.querySelectorAll('[data-theme-preview]').forEach(a=>a.href='/preview/'+encodeURIComponent(a.dataset.page)+'?theme='+encodeURIComponent(a.dataset.themePreview));}}
app.addEventListener('input',event=>{if(event.target.id==='template-search')filterLibrary();});
app.addEventListener('change',event=>{if(['template-type','template-category'].includes(event.target.id))filterLibrary();});

function chromePreviewURL(anchor=''){const home=state.pages.find(p=>p.slug==='')||state.pages[0];if(!home)return '';const query=new URLSearchParams();for(const key of ['headerStyle','footerStyle','megaStyle'])query.set(key,state.site[key]||({headerStyle:'classic',footerStyle:'classic',megaStyle:'columns'})[key]);return '/preview/'+encodeURIComponent(home.id)+'?'+query+(anchor?'#'+anchor:'');}
function chromeDesignPanel(){return '<section class="panel chrome-design-panel"><div class="panel-head"><div><h2>Header, footer & mega-menu designs</h2><p>Mix these designs with any website template. Your links stay in place.</p></div></div><div class="panel-body">'+[['headerStyle','Header designs','header'],['footerStyle','Footer designs','footer'],['megaStyle','Mega-menu designs','mega']].map(([key,title,kind])=>'<fieldset class="chrome-picker"><legend>'+title+'</legend><div class="chrome-options">'+state.chrome[key].map(choice=>'<label class="chrome-option"><input type="radio" name="'+key+'" data-menu-setting="'+key+'" value="'+E(choice.id)+'" '+((state.site[key]||state.chrome[key][0].id)===choice.id?'checked':'')+'><span class="chrome-swatch swatch-'+kind+' swatch-'+E(choice.id)+'" aria-hidden="true"><b></b><i></i><i></i><i></i><i></i></span><strong>'+E(choice.name)+'</strong><small>'+E(choice.description)+'</small></label>').join('')+'</div></fieldset>').join('')+'<div class="notice">Mega-menu designs apply to groups using a mega layout. Add child links or columns below, then open the group in the preview. Menus remain expandable on mobile.</div><div class="actions"><a class="btn" id="chrome-preview-header" href="'+E(chromePreviewURL())+'" target="_blank" rel="noopener">Preview header & menu ↗</a><a class="btn" id="chrome-preview-footer" href="'+E(chromePreviewURL('site-footer'))+'" target="_blank" rel="noopener">Preview footer ↗</a></div><p class="chrome-help">Previews use your saved pages and menus with the designs selected above. Save navigation, then publish to update the public website.</p></div></section>';}
app.addEventListener('change',event=>{if(['headerStyle','footerStyle','megaStyle'].includes(event.target.dataset.menuSetting)){const header=$('#chrome-preview-header'),footer=$('#chrome-preview-footer');if(header)header.href=chromePreviewURL();if(footer)footer.href=chromePreviewURL('site-footer');}});

function newPlan(name='Plan'){return {name,description:'',price:'',period:'',previousPrice:'',badge:'',featured:false,button:'Get in touch',link:'',linkPage:'',features:[{label:'Feature',value:'Included'}]};}
function newPricing(){return {layout:'cards',skin:'clean',currency:'',note:'Add your billing, renewal and tax terms here.',plans:['Starter','Professional','Enterprise'].map(name=>newPlan(name))};}
function pricingForm(s){s.pricing??=newPricing();const p=s.pricing;return '<form id="section-form"><label class="check"><input type="checkbox" name="hidden" '+(s.hidden?'checked':'')+'>Hide this section</label><div class="form-grid">'+field('Eyebrow / small label','eyebrow',s.eyebrow)+field('Heading','title',s.title)+field('Introduction','text',s.text,'textarea')+select('Pricing layout','pricing.layout',p.layout,[['cards','Horizontal cards'],['rows','Horizontal rows'],['stacked','Vertical cards'],['comparison','Feature comparison'],['compact','Compact list']])+select('Table colour style','pricing.skin',p.skin,[['clean','Clean'],['soft','Soft colour'],['outline','Outlined'],['contrast','Dark contrast']])+field('Currency or price prefix','pricing.currency',p.currency,'text','For example $, €, £ or USD. Leave empty for custom price text.')+field('Billing, renewal and tax note','pricing.note',p.note,'textarea')+'</div><div class="notice">This table belongs only to this page. Prices are display text; buttons can open a page, contact form or your checkout URL. No payment processing is performed by this section.</div>'+p.plans.map((plan,i)=>'<fieldset class="pricing-editor-plan"><legend>Plan '+(i+1)+' · '+E(plan.name)+'</legend><div class="actions">'+btn('↑','pricing-up','','','data-index="'+i+'" aria-label="Move plan up"')+btn('↓','pricing-down','','','data-index="'+i+'" aria-label="Move plan down"')+btn('Duplicate','pricing-copy','copy','','data-index="'+i+'"')+btn('Remove','pricing-remove','trash','danger','data-index="'+i+'"')+'</div><div class="form-grid">'+field('Plan name','plan.'+i+'.name',plan.name)+field('Price','plan.'+i+'.price',plan.price,'text','Use your actual price, Free, or Contact us.')+field('Billing period','plan.'+i+'.period',plan.period,'text','For example /month, /year or one-time.')+field('Previous price (optional)','plan.'+i+'.previousPrice',plan.previousPrice)+field('Badge (optional)','plan.'+i+'.badge',plan.badge)+field('Short description','plan.'+i+'.description',plan.description,'textarea')+field('Button label','plan.'+i+'.button',plan.button)+select('Button destination page','plan.'+i+'.linkPage',plan.linkPage||'',[['','Use a custom URL'],...state.pages.map(p=>[p.id,p.title])])+field('Custom button URL','plan.'+i+'.link',plan.link,'text','https://, /path/, mailto: or tel:')+'<div class="span-2">'+field('Features — one per line: Feature | Value','plan.'+i+'.features',plan.features.map(f=>f.label+' | '+f.value).join('\n'),'textarea','Use the same feature names across plans for an aligned comparison table.')+'</div></div><label class="check"><input type="checkbox" name="plan.'+i+'.featured" '+(plan.featured?'checked':'')+'>Highlight this plan</label></fieldset>').join('')+btn('Add plan','pricing-add','plus')+'<p class="footnote">Up to 12 plans and 40 features per plan. Save and preview before publishing.</p></form>';}
function capturePricing(form,s){for(const key of ['eyebrow','title','text'])s[key]=form.elements.namedItem(key)?.value||'';s.hidden=form.elements.hidden.checked;for(const key of ['layout','skin','currency','note'])s.pricing[key]=form.elements.namedItem('pricing.'+key)?.value||'';s.pricing.plans.forEach((plan,i)=>{for(const key of ['name','description','price','period','previousPrice','badge','button','link','linkPage'])plan[key]=form.elements.namedItem('plan.'+i+'.'+key)?.value||'';plan.featured=!!form.elements.namedItem('plan.'+i+'.featured')?.checked;plan.features=(form.elements.namedItem('plan.'+i+'.features')?.value||'').split('\n').filter(line=>line.trim()).slice(0,40).map(line=>{const [label,...value]=line.split('|');return {label:label.trim(),value:value.join('|').trim()||'Included'};});});}

if(CMS_BASE){const fix=root=>{for(const el of root.querySelectorAll('[href],[src]'))for(const key of ['href','src']){const value=el.getAttribute(key);if(value?.startsWith('/')&&!value.startsWith('//')&&!value.startsWith(CMS_BASE+'/')&&value!==CMS_BASE)el.setAttribute(key,CMS_BASE+value);}};new MutationObserver(()=>fix(document)).observe(document.documentElement,{childList:true,subtree:true,attributes:true,attributeFilter:['href','src']});fix(document);}

function maintenanceScreen(){return heading('Your website. Safely in your hands.','PHP edition · Browser backups and recovery without SSH.')+'<section class="panel"><div class="panel-head"><h2>Hosting health</h2><button class="btn" data-action="php-health-refresh">Run checks again</button></div><div class="panel-body" id="php-health-report" role="status">Checking this installation…</div></section><section class="panel"><div class="panel-head"><h2>Download a full backup</h2></div><div class="panel-body"><p>Includes accounts, pages, histories, inbox and original images. Database credentials and active sessions are excluded. Keep backups private.</p><form id="php-backup-form"><label>Current owner password<input type="password" name="password" required autocomplete="current-password"></label><label>Backup protection<select name="protection"><option value="encrypted">Password-encrypted ZIP (recommended)</option><option value="plain">Unencrypted ZIP</option></select></label><label>Separate backup passphrase<input type="password" name="archivePassword" minlength="12" maxlength="256" autocomplete="new-password"></label><label>Confirm backup passphrase<input type="password" name="archiveConfirm" minlength="12" maxlength="256" autocomplete="new-password"></label><p>For encrypted backups, use a unique passphrase and save it separately. Lost backup passphrases cannot be recovered. File names remain visible. The private on-server safety backups made during restores are unencrypted.</p><button class="btn primary">Create and download backup ZIP</button></form></div></section><section class="panel"><div class="panel-head"><h2>Restore a PHP-edition backup</h2></div><div class="panel-body"><p>Restoration replaces site data and revokes sessions. A safety backup is made first. PHP-edition backups are separate from Node-edition backups.</p><form id="php-restore-form"><label>PHP backup ZIP<input type="file" name="backup" accept=".zip" required></label><label>Backup passphrase (encrypted ZIP only)<input type="password" name="archivePassword" autocomplete="off" maxlength="256"></label><label>Current owner password<input type="password" name="password" required autocomplete="current-password"></label><button class="btn">Restore backup</button></form></div></section><section class="panel"><div class="panel-head"><h2>Updates and hosting</h2></div><div class="panel-body"><p>For this release, back up first, then extract a verified PHP-edition release over the application files using File Manager. Preserve app/installed.php and the private storage directory. Do not delete the old installation folder or use a Node-edition ZIP.</p><p>Updates are installed manually through File Manager; signed browser code updates are not available. Current host requirements: patched PHP 8.3+, PDO MySQL or SQLite, GD, Fileinfo, mbstring, OpenSSL and ZIP. Scheduling uses your hosting control panel cron.</p><a class="btn" href="'+CMS_BASE+'/api/health" target="_blank" rel="noopener">View owner health report ↗</a></div></section>';}
document.addEventListener('click',event=>{const a=event.target.closest('a');if(a&&['/api/backup','/api/backup/full'].some(p=>a.getAttribute('href')===CMS_BASE+p||a.getAttribute('href')===p)){event.preventDefault();navigate('maintenance');}},true);
app.addEventListener('submit',async event=>{const form=event.target;if(!['php-backup-form','php-restore-form','php-recovery-code-form'].includes(form.id))return;event.preventDefault();try{if(form.id==='php-backup-form'){const encrypted=form.elements.protection.value==='encrypted';let response;if(encrypted){const pass=form.elements.archivePassword.value;if(pass.length<12||pass!==form.elements.archiveConfirm.value)throw new Error('Enter and confirm a separate backup passphrase of at least 12 characters.');response=await fetch(CMS_BASE+'/api/backup/encrypted',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':state.csrf},body:JSON.stringify({password:form.elements.password.value,factor:form.elements.factor?.value||'',archivePassword:pass,archiveConfirm:form.elements.archiveConfirm.value})});}else{const grant=await api('/backup-ticket','POST',{password:form.elements.password.value,factor:form.elements.factor?.value||''});response=await fetch(CMS_BASE+'/api/backup/full?ticket='+encodeURIComponent(grant.ticket));}form.elements.password.value='';form.elements.archivePassword.value='';form.elements.archiveConfirm.value='';if(!response.ok)throw new Error((await response.json()).error||'Backup failed.');const url=URL.createObjectURL(await response.blob()),a=document.createElement('a');a.href=url;a.download=encrypted?'1DED-PHP-encrypted-backup.zip':'1DED-PHP-full-backup.zip';a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);toast('Backup downloaded. Store it privately.');}else if(form.id==='php-restore-form'){if(!await confirmAction('Restore this backup?','Current site data will be replaced. A safety backup is created first; all sessions will be signed out.'))return;const response=await fetch(CMS_BASE+'/api/restore',{method:'POST',headers:{'X-CSRF-Token':state.csrf},body:new FormData(form)});const result=await response.json();if(!response.ok)throw new Error(result.error);form.elements.password.value='';state=null;authMode='login';authView();toast('Backup restored. Sign in with the restored account.');}else{const result=await api('/recovery-code','POST',{current:form.elements.current.value,factor:form.elements.factor?.value||''});form.elements.current.value='';$('#php-recovery-code').textContent=result.code;toast('Save the new recovery code. The previous code no longer works.');}}catch(error){toast(error.message,true);}});
const phpOriginalAccount=account;account=function(){return phpOriginalAccount()+(state.user.role==='owner'?'<section class="panel"><div class="panel-head"><h2>Owner recovery code</h2></div><div class="panel-body"><p>Save your recovery code offline. Use '+location.origin+CMS_BASE+'/recover/ to regain access without SSH. Generate a replacement if the previous code was lost or exposed.</p><form id="php-recovery-code-form"><label>Current owner password<input type="password" name="current" required autocomplete="current-password"></label><button class="btn">Generate replacement recovery code</button></form><pre id="php-recovery-code"></pre></div></section>':'');};

let phpMfaChallenge='',phpEnrollment=null,phpSecurityCodes=[];
const phpBaseAuthView=authView;authView=function(error=''){phpSecurityCodes=[];phpEnrollment=null;if(!phpMfaChallenge){phpBaseAuthView(error);return;}app.innerHTML='<main class="auth-main" style="min-height:100vh"><form id="php-mfa-login-form" class="auth-form"><h2>One more step.</h2><p>Enter your authenticator’s six-digit code or an unused MFA recovery code. This login expires after five minutes.</p>'+ (error?'<div class="error" role="alert">'+E(error)+'</div>':'')+'<label>Authenticator or MFA recovery code<input name="code" required autocomplete="one-time-code" maxlength="50" autofocus></label><button class="btn primary">Verify and sign in</button><button type="button" class="btn" data-action="php-mfa-cancel">Back to password sign-in</button></form></main>';};
function phpSecurityPanel(){return '<section class="panel"><div class="panel-head"><h2>Two-factor authentication</h2></div><div id="php-security-content" class="panel-body">Loading account protection…</div></section><section class="panel"><div class="panel-head"><h2>Your active sessions</h2>'+btn('Sign out other sessions','php-sessions-others','shield')+'</div><div id="php-sessions-content" class="panel-body">Loading sessions…</div></section>';}
const phpAccountWithRecovery=account;account=function(){return phpAccountWithRecovery()+phpSecurityPanel();};
function factorField(){return '<label>Authenticator or MFA recovery code<input name="factor" required autocomplete="one-time-code" maxlength="50"><small>Use a fresh code. Authenticator codes and recovery codes cannot be reused.</small></label>';}
const phpOriginalRender=render;render=function(){if(view!=='account'){phpSecurityCodes=[];phpEnrollment=null;}phpOriginalRender();if(state?.user.mfaEnabled)for(const id of ['password-form','php-backup-form','php-restore-form','php-recovery-code-form']){const form=document.getElementById(id);if(form&&!form.elements.factor)form.querySelector('button').insertAdjacentHTML('beforebegin',factorField());}if(view==='account')loadPhpSecurity();};
async function loadPhpSecurity(){try{const [security,sessions]=await Promise.all([api('/security'),api('/sessions')]);const target=$('#php-security-content');if(!target)return;state.user.mfaEnabled=security.enabled;target.innerHTML='<div class="notice">'+(security.enabled?'Enabled · '+security.recoveryCodesRemaining+' single-use MFA recovery codes remaining.':'Not enabled. Add an authenticator app for an extra sign-in step.')+'</div>'+(security.enabled?'<form id="php-mfa-codes-form"><h3>Replace MFA recovery codes</h3><p>Replaces every old MFA recovery code. Save the new set privately.</p><label>Current password<input type="password" name="current" required autocomplete="current-password"></label>'+factorField()+'<button class="btn">Generate new MFA recovery codes</button></form><hr><form id="php-mfa-disable-form"><h3>Disable two-factor authentication</h3><label>Current password<input type="password" name="current" required autocomplete="current-password"></label>'+factorField()+'<button class="btn">Disable two-factor authentication</button></form>':'<form id="php-mfa-begin-form"><label>Current password<input type="password" name="current" required autocomplete="current-password"></label><button class="btn primary">Set up authenticator app</button></form>')+'<div id="php-mfa-enrollment"></div><pre id="php-mfa-codes" style="white-space:pre-wrap;overflow-wrap:anywhere"></pre><p style="font-size:12px">Authenticator apps work offline. No SMS, external account, or remote QR service is required. Owner emergency recovery remains available with the separate code saved at installation.</p>';if(phpSecurityCodes.length)$('#php-mfa-codes').textContent='Save these MFA recovery codes privately. Each works once.\n\n'+phpSecurityCodes.join('\n');$('#php-sessions-content').innerHTML=sessions.map(session=>'<div class="release-row"><div><strong>'+(session.current?'This browser session':'Another signed-in session')+'</strong><small>Expires '+E(date(session.expires))+'</small></div>'+(session.current?'<span class="tag neutral">Current</span>':btn('Sign out','php-session-revoke','logout','','data-id="'+E(session.id)+'"'))+'</div>').join('')||'<p>No active sessions.</p>';}catch(error){toast(error.message,true);}}
app.addEventListener('click',async event=>{const button=event.target.closest('[data-action]');if(!button)return;const a=button.dataset.action;try{if(a==='php-mfa-cancel'){phpMfaChallenge='';authMode='login';authView();}else if(a==='php-sessions-others'){await api('/sessions/revoke-others','POST',{});await loadPhpSecurity();toast('Other account sessions signed out.');}else if(a==='php-session-revoke'){await api('/sessions/'+button.dataset.id,'DELETE');await loadPhpSecurity();toast('Session signed out.');}}catch(error){toast(error.message,true);}});
app.addEventListener('submit',async event=>{const form=event.target;if(!form.id?.startsWith('php-mfa-'))return;event.preventDefault();const data=Object.fromEntries(new FormData(form)),button=form.querySelector('button');button.disabled=true;try{if(form.id==='php-mfa-login-form'){await api('/login/mfa','POST',{challenge:phpMfaChallenge,code:data.code});phpMfaChallenge='';await refresh();view='dashboard';render();return;}if(form.id==='php-mfa-begin-form'){phpEnrollment=await api('/security/mfa/begin','POST',data);form.elements.current.value='';$('#php-mfa-enrollment').innerHTML='<h3>Add this account to your authenticator</h3><p>Choose manual setup / enter a setup key in your authenticator. Use account '+E(phpEnrollment.account)+', issuer 1DED Free CMS, time-based codes, six digits and a 30-second period.</p><pre id="php-mfa-key" style="white-space:pre-wrap;overflow-wrap:anywhere"></pre><p>This setup expires in ten minutes. Two-factor authentication stays off until you verify a code.</p><form id="php-mfa-confirm-form"><label>Six-digit authenticator code<input name="code" required inputmode="numeric" pattern="[0-9]{6}" autocomplete="one-time-code"></label><button class="btn primary">Confirm and enable two-factor authentication</button></form>';$('#php-mfa-key').textContent=phpEnrollment.secret;return;}if(form.id==='php-mfa-confirm-form'){const result=await api('/security/mfa/confirm','POST',{enrollment:phpEnrollment.enrollment,code:data.code});phpEnrollment=null;phpSecurityCodes=result.codes;await refresh();render();toast('Two-factor authentication enabled. Other sessions were signed out.');return;}if(form.id==='php-mfa-disable-form'){if(!await confirmAction('Disable two-factor authentication?','Future sign-ins will use only your password. Other sessions will be signed out.'))return;await api('/security/mfa/disable','POST',data);phpSecurityCodes=[];await refresh();render();toast('Two-factor authentication disabled.');return;}if(form.id==='php-mfa-codes-form'){const result=await api('/security/mfa/codes','POST',data);form.reset();phpSecurityCodes=result.codes;await loadPhpSecurity();toast('The old MFA recovery codes no longer work.');}}catch(error){if(form.id==='php-mfa-login-form')authView(error.message);else toast(error.message,true);}finally{button.disabled=false;}});

let phpHealthRequest=0;
async function loadHostingHealth(){const target=$('#php-health-report');if(!target)return;const request=++phpHealthRequest;target.textContent='Checking this installation…';try{const report=await api('/health');if(request!==phpHealthRequest||!target.isConnected)return;target.innerHTML='<p>PHP '+E(report.php)+' · '+E(report.database)+' · '+E(report.version)+'</p>'+report.checks.map(check=>'<div class="release-row"><div><strong>'+E(check.label)+'</strong><p>'+E(check.message)+'</p></div><span class="tag '+(check.status==='pass'?'neutral':'')+'">'+E({pass:'Passed',warning:'Review',error:'Action needed'}[check.status])+'</span></div>').join('')+'<p>Checks run '+E(date(report.checkedAt))+'. These checks do not replace a hosting review or security audit.</p>';const changes=[...(report.integrity.missing||[]).map(p=>'Missing: '+p),...(report.integrity.changed||[]).map(p=>'Changed: '+p)];if(changes.length){const details=document.createElement('details'),summary=document.createElement('summary'),pre=document.createElement('pre');summary.textContent='Review application files ('+changes.length+')';pre.style.whiteSpace='pre-wrap';pre.style.overflowWrap='anywhere';pre.textContent=changes.join('\n');details.append(summary,pre);target.append(details);}}catch(error){if(target.isConnected)target.textContent='Health checks could not finish: '+error.message;}}
app.addEventListener('click',event=>{if(event.target.closest('[data-action="php-health-refresh"]'))loadHostingHealth();});
